import { assetBase as defaultAssetBase, type StudioConfig } from "./config";
import type { ProfileData } from "./data/types";
import { esc } from "./lib/escape";
import { assetFileName, createCtx, layoutParts, renderPart, type PartMeta } from "./render";
import type { Mode } from "./theme";

export interface ReadmeOptions {
  /** base URL the assets are served from (defaults to the raw URL of the asset branch) */
  assetBase?: string;
  /** override mode list (defaults to config.output.modes) */
  modes?: Mode[];
  /** include the "generated by" HTML comment (default true) */
  banner?: boolean;
  date?: Date;
}

function widthFor(count: number): string {
  if (count <= 1) return "100%";
  return `${Math.floor(100 / count) - 1}%`;
}

function picture(base: string, part: PartMeta, modes: Mode[], size: string): string {
  const src = (m: Mode) => `${base}/${assetFileName(part.name, m, part.kind)}`;
  const fallback = modes.includes("dark") ? "dark" : modes[0];
  const sources =
    modes.length > 1 ? modes.map((m) => `<source media="(prefers-color-scheme: ${m})" srcset="${src(m)}">`).join("") : "";
  const img = `<img alt="${esc(part.alt)}" src="${src(fallback)}" ${size}>`;
  const pic = sources ? `<picture>${sources}${img}</picture>` : img;
  return part.href ? `<a href="${esc(part.href)}">${pic}</a>` : pic;
}

/**
 * Compose the README: each layout row becomes a centred paragraph of theme-aware
 * <picture> elements; markdown widgets are emitted verbatim between them.
 */
export function renderReadme(config: StudioConfig, data: ProfileData, o: ReadmeOptions = {}): string {
  const base = (o.assetBase ?? defaultAssetBase(config)).replace(/\/+$/, "");
  const modes = o.modes ?? config.output.modes;
  const rows = layoutParts(config, data);
  const out: string[] = [];
  if (o.banner !== false) {
    out.push(
      `<!--\n  Generated by Readme Studio (https://github.com/DavidNiessen/readme-studio).\n  Edit readme.config.json, or open it in the studio, instead of this file:\n  it is rebuilt by .github/workflows/readme.yml.\n-->`,
    );
  }
  let mdCtx: ReturnType<typeof createCtx> | null = null;
  config.layout.forEach((row, ri) => {
    const parts = rows[ri];
    if (!parts.length) return;
    const align = row.align;
    // split into runs of images and markdown
    let run: PartMeta[] = [];
    const flush = () => {
      if (!run.length) return;
      const fluid = run.filter((p) => !p.fixedHeight).length;
      const items = run.map((p) => picture(base, p, modes, p.fixedHeight ? `height="${p.fixedHeight}"` : `width="${widthFor(fluid)}"`));
      out.push(`<p align="${align}">\n${items.join("\n")}\n</p>`);
      run = [];
    };
    for (const p of parts) {
      if (p.kind === "markdown") {
        flush();
        mdCtx ??= createCtx(config, data, modes[0], { date: o.date });
        const md = renderPart(p, mdCtx).trim();
        if (md) out.push(align === "left" ? md : `<div align="${align}">\n\n${md}\n\n</div>`);
      } else run.push(p);
    }
    flush();
  });
  return `${out.join("\n\n")}\n`;
}
